const fs=require('node:fs'),assert=require('node:assert/strict')
const sql=fs.readFileSync('supabase/migrations/20261020165500_financeiro_cancelamento_recebimento_master_v1.sql','utf8')
const api=fs.readFileSync('app/api/financeiro/recebimentos-cancelar/route.ts','utf8')
const ui=fs.readFileSync('components/clientes/VendaObraCentral.tsx','utf8')
const check=(value,regex)=>assert.match(value,regex)
check(sql,/v_operador\.role<>'master'/)
check(sql,/char_length\(trim\(coalesce\(p_justificativa,''\)\)\) not between 10 and 1000/)
check(sql,/for update/)
check(sql,/jsonb_agg\(to_jsonb\(a\)/)
check(sql,/insert into public\.financeiro_recebimentos_cancelamentos/)
check(sql,/update public\.financeiro_contas_receber/)
check(sql,/delete from public\.financeiro_recebimento_alocacoes/)
check(sql,/set status='cancelado'/)
check(sql,/balcao_caixas c/)
check(sql,/c\.status<>'aberto'/)
check(sql,/tipo.*'estorno'/s)
check(sql,/revoke all on function public\.fn_financeiro_cancelar_recebimento_master_v1/)
check(api,/u\.role!=='master'/)
check(api,/process\.env\.VERCEL_ENV==='preview'/)
check(api,/p_empresa:u\.empresa_id/)
check(ui,/Corrigir valor/)
check(ui,/Cancelar recebimento/)
check(ui,/justificativa\.trim\(\)\.length<10/)
check(ui,/hist[oó]rico/i)
console.log('PASS: Master, justificativa, estorno das parcelas, Caixa e trilha de auditoria, prévia sem escrita.')
